import Foundation

/// UI text in 43 languages, one row per language in the order of the properties below.
/// Where macOS has its own wording, the row carries it, taken from the system's localization
/// tables: Open Recent and Clear Menu from AppKit's MenuCommands, Cancel from its Common table,
/// Show all filename extensions from Finder.
/// A row that doesn't have every entry falls back to English as a whole.
struct Strings {
    private let v: [String]

    var open: String { v[0] }
    var paste: String { v[1] }
    var dropHint: String { v[2] }
    var formatHint: String { v[3] }
