    var clickBack: String { v[13] }
    var dontKnow: String { v[14] }
    var know: String { v[15] }
    var shuffle: String { v[16] }
    var reset: String { v[17] }
    var resetTitle: String { v[18] }
    var resetBody: String { v[19] }
    var resetButton: String { v[20] }
    var cancel: String { v[21] }
    var done: String { v[22] }
    var total: String { v[23] }
    var retryMissed: String { v[24] }
    var retryAll: String { v[25] }
    var perfect: String { v[26] }
    var bad: String { v[27] }
    var normal: String { v[28] }
    func unrated(_ n: Int) -> String { String(format: v[29], n) }
    var listen: String { v[30] }
    var flip: String { v[31] }
    var previous: String { v[32] }
    var next: String { v[33] }
    var deck: String { v[34] }
    var openRecent: String { v[35] }
    var clearMenu: String { v[36] }
    var first: String { v[37] }
    var last: String { v[38] }
    var reading: String { v[39] }
    var readSystem: String { v[40] }
    var readPolish: String { v[41] }
    var readPolishInfo: String { v[42] }
    var voices: String { v[43] }
    /// Finder's own wording, from its settings.
    var showExtensions: String { v[44] }
    func removeTitle(_ name: String) -> String { String(format: v[45], name) }
    var removeBody: String { v[46] }
    var clearTitle: String { v[47] }
    var clearBody: String { v[48] }

    private static let count = 49

    static func `for`(_ code: String) -> Strings {
        let row = table[code] ?? []
        return Strings(v: row.count == count ? row : table["en"]!)
    }

    /// The app's language: the first of the system's preferred languages that the bundle has
    /// (build.sh makes an .lproj for each row here), so a per-app language from System
    /// Settings → General → Language & Region counts too.
    static let code: String = {
        if let first = Bundle.main.preferredLocalizations.first, table[first] != nil { return first }
        for id in Locale.preferredLanguages {
            if table[id] != nil { return id }
            let lang = Locale.Language(identifier: id)
            guard let code = lang.languageCode?.identifier else { continue }
            if code == "zh" {
                let hant = lang.script?.identifier == "Hant" || ["TW", "HK", "MO"].contains(lang.region?.identifier ?? "")
                return hant ? "zh-Hant" : "zh-Hans"
            }
            if code == "no" || code == "nn" { return "nb" }
            if table[code] != nil { return code }
        }
        return "en"
    }()

    static let current = Strings.for(code)
    static let rtl = ["ar", "he", "fa"].contains(code)

